/** Interleave two sorted arrays into one sorted array. */
function merge(a: number[], b: number[]): number[] {
  const out: number[] = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] <= b[j]) out.push(a[i++]);
    else out.push(b[j++]);
  }
  return out.concat(a.slice(i), b.slice(j));
}

/** Stable merge sort — split, sort the halves, merge. */
export function mergeSort(xs: readonly number[]): number[] {
  if (xs.length <= 1) return [...xs];
  const mid = Math.floor(xs.length / 2);
  return merge(mergeSort(xs.slice(0, mid)), mergeSort(xs.slice(mid)));
}

